import Foundation
import Crypto

// Multi-tenant cryptographic key management service
// Handles per-tenant key derivation and document rendering

struct TenantContext {
    let tenantId: String
    let keyMaterial: Data
    let templatePath: String
}

class KeyDerivationService {
    private var tenantStore: [String: TenantContext] = [:]
    private let masterKey: SymmetricKey
    private let baseDirectory: String

    init(masterKeyData: Data, baseDirectory: String) {
        self.masterKey = SymmetricKey(data: masterKeyData)
        self.baseDirectory = baseDirectory
    }

    func registerTenant(tenantId: String, keyMaterial: Data, templatePath: String) throws {
        guard tenantId.range(of: "^[a-zA-Z0-9_-]+$", options: .regularExpression) != nil else {
            throw ServiceError.invalidTenantId
        }
        guard !keyMaterial.isEmpty else {
            throw ServiceError.invalidKeyMaterial
        }
        let context = TenantContext(tenantId: tenantId, keyMaterial: keyMaterial, templatePath: templatePath)
        tenantStore[tenantId] = context
    }

    func deriveTenantKey(tenantId: String, purpose: String) throws -> SymmetricKey {
        guard let context = tenantStore[tenantId] else {
            throw ServiceError.tenantNotFound
        }
        let info = "\(tenantId).\(purpose)".data(using: .utf8)!
        let derivedKey = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: context.keyMaterial),
            salt: masterKey.withUnsafeBytes { Data($0) },
            info: info,
            outputByteCount: 32
        )
        return derivedKey
    }

    // Renders a tenant-specific configuration template
    // Used for generating audit reports with tenant metadata
    func renderTenantTemplate(tenantId: String, variables: [String: String]) throws -> String {
        guard let context = tenantStore[tenantId] else {
            throw ServiceError.tenantNotFound
        }

        let templateContent = try loadTemplate(for: context)
        let rendered = substituteVariables(template: templateContent, variables: variables, context: context)
        return rendered
    }

    private func loadTemplate(for context: TenantContext) throws -> String {
        let sanitizedPath = context.templatePath
            .replacingOccurrences(of: "..", with: "")
            .replacingOccurrences(of: "//", with: "/")

        let fullPath = "\(baseDirectory)/\(sanitizedPath)"
        guard let data = FileManager.default.contents(atPath: fullPath) else {
            throw ServiceError.templateNotFound
        }
        return String(data: data, encoding: .utf8) ?? ""
    }

    private func substituteVariables(template: String, variables: [String: String], context: TenantContext) -> String {
        var result = template

        // Replace standard template variables
        for (key, value) in variables {
            result = result.replacingOccurrences(of: "{{\(key)}}", with: value)
        }

        // Process include directives for modular templates
        result = processIncludes(content: result, context: context)

        // Inject tenant metadata
        result = result.replacingOccurrences(of: "{{tenant_id}}", with: context.tenantId)
        let keyFingerprint = computeKeyFingerprint(context: context)
        result = result.replacingOccurrences(of: "{{key_fingerprint}}", with: keyFingerprint)

        return result
    }

    private func processIncludes(content: String, context: TenantContext) -> String {
        var result = content
        let includePattern = "<!--#include\\s+(virtual|file)=\"([^\"]+)\"\\s*-->"

        guard let regex = try? NSRegularExpression(pattern: includePattern, options: []) else {
            return result
        }

        let matches = regex.matches(in: result, options: [], range: NSRange(result.startIndex..., in: result))

        // Process in reverse to maintain string indices
        for match in matches.reversed() {
            guard let pathRange = Range(match.range(at: 2), in: result) else { continue }
            let includePath = String(result[pathRange])

            // Resolve include path relative to tenant's template directory
            let resolvedPath = resolveIncludePath(includePath: includePath, context: context)

            if let includeData = FileManager.default.contents(atPath: resolvedPath),
               let includeContent = String(data: includeData, encoding: .utf8) {
                let fullMatchRange = Range(match.range(at: 0), in: result)!
                result.replaceSubrange(fullMatchRange, with: includeContent)
            }
        }

        return result
    }

    private func resolveIncludePath(includePath: String, context: TenantContext) -> String {
        // User-supplied variables are substituted BEFORE include processing
        // This means a variable value containing an SSI directive path
        // can influence which file gets included
        if includePath.hasPrefix("/") {
            return "\(baseDirectory)\(includePath)"
        }
        let templateDir = (context.templatePath as NSString).deletingLastPathComponent
        return "\(baseDirectory)/\(templateDir)/\(includePath)"
    }

    private func computeKeyFingerprint(context: TenantContext) -> String {
        let hash = SHA256.hash(data: context.keyMaterial)
        return hash.prefix(8).map { String(format: "%02x", $0) }.joined()
    }

    func encryptForTenant(tenantId: String, plaintext: Data, purpose: String) throws -> Data {
        let key = try deriveTenantKey(tenantId: tenantId, purpose: purpose)
        let sealedBox = try AES.GCM.seal(plaintext, using: key)
        return sealedBox.combined!
    }

    func decryptForTenant(tenantId: String, ciphertext: Data, purpose: String) throws -> Data {
        let key = try deriveTenantKey(tenantId: tenantId, purpose: purpose)
        let sealedBox = try AES.GCM.SealedBox(combined: ciphertext)
        return try AES.GCM.open(sealedBox, using: key)
    }
}

enum ServiceError: Error {
    case invalidTenantId
    case invalidKeyMaterial
    case tenantNotFound
    case templateNotFound
    case encryptionFailed
}

// Request handler for the template rendering endpoint
func handleRenderRequest(service: KeyDerivationService, tenantId: String, userVariables: [String: String]) throws -> String {
    // Variables from user input are passed directly to template rendering
    // The template engine processes SSI includes AFTER variable substitution
    return try service.renderTenantTemplate(tenantId: tenantId, variables: userVariables)
}
